import { index, integer, sqliteTable, text, uniqueIndex } from "drizzle-orm/sqlite-core";
import { idColumn, tenantColumns, timestampColumns } from "./_shared";

const NOTIFICATION_KINDS = [
  "issue_assigned",
  "issue_status_changed",
  "issue_due_soon",
  "issue_overdue",
  "comment_created",
  "comment_mention",
  "member_invited",
  "member_joined",
  "project_archived",
  "plan_limit_reached",
  "digest_ready",
] as const;

export const notifications = sqliteTable(
  "notifications",
  {
    id: idColumn(),
    ...tenantColumns,
    recipientId: text("recipient_id").notNull(),
    kind: text("kind", { enum: NOTIFICATION_KINDS }).notNull(),
    title: text("title").notNull(),
    body: text("body").notNull(),
    href: text("href").notNull(),
    actorId: text("actor_id"),
    readAt: text("read_at"),
    /** JSON array of `NotificationChannel`. */
    channels: text("channels").notNull().default('["in_app"]'),
    ...timestampColumns,
  },
  (table) => [
    index("notifications_org_recipient_idx").on(table.orgId, table.recipientId),
    index("notifications_org_read_idx").on(table.orgId, table.readAt),
  ],
);

export const notificationPreferences = sqliteTable(
  "notification_preferences",
  {
    ...tenantColumns,
    userId: text("user_id").notNull(),
    kind: text("kind", { enum: NOTIFICATION_KINDS }).notNull(),
    inApp: integer("in_app", { mode: "boolean" }).notNull().default(true),
    email: integer("email", { mode: "boolean" }).notNull().default(true),
    digestOnly: integer("digest_only", { mode: "boolean" })
      .notNull()
      .default(false),
  },
  (table) => [
    uniqueIndex("notification_preferences_pk").on(
      table.orgId,
      table.userId,
      table.kind,
    ),
  ],
);

export type NotificationRow = typeof notifications.$inferSelect;
export type NewNotificationRow = typeof notifications.$inferInsert;
export type NotificationPreferenceRow =
  typeof notificationPreferences.$inferSelect;
import { index, sqliteTable, text } from "drizzle-orm/sqlite-core";
import { idColumn, tenantColumns } from "./_shared";

export const activityEvents = sqliteTable(
  "activity_events",
  {
    id: idColumn(),
    ...tenantColumns,
    action: text("action").notNull(),
    actorId: text("actor_id"),
    subjectKind: text("subject_kind", {
      enum: [
        "organization",
        "project",
        "issue",
        "comment",
        "member",
        "subscription",
        "feature_flag",
      ],
    }).notNull(),
    subjectId: text("subject_id").notNull(),
    projectId: text("project_id"),
    summary: text("summary").notNull(),
    /** JSON object of scalar metadata. */
    metadata: text("metadata").notNull().default("{}"),
    occurredAt: text("occurred_at").notNull(),
  },
  (table) => [
    index("activity_org_occurred_idx").on(table.orgId, table.occurredAt),
    index("activity_org_action_idx").on(table.orgId, table.action),
    index("activity_org_subject_idx").on(table.orgId, table.subjectKind, table.subjectId),
  ],
);

export type ActivityEventRow = typeof activityEvents.$inferSelect;
export type NewActivityEventRow = typeof activityEvents.$inferInsert;
