/**
 * Milestone domain rules that do not need the database: the state-conflict
 * error, name normalisation, overdue and the listing order.
 */
import type { IsoTimestamp } from "@/types/common";
import type {
  Milestone,
  MilestoneProgress,
  MilestoneWithProgress,
} from "@/types/milestone";

export type MilestoneStateReason =
  | "closed"
  | "already_open"
  | "too_many_open"
  | "name_taken";

const MESSAGES: Readonly<Record<MilestoneStateReason, string>> = {
  closed: "is closed",
  already_open: "is already open",
  too_many_open: "cannot be opened: the project has too many open milestones",
  name_taken: "uses a name already taken in this project",
};

/** A milestone is not in the state the operation needs; maps to `conflict`. */
export class MilestoneStateError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly reason: MilestoneStateReason,
    readonly milestoneId: string | null = null,
  ) {
    super(`Milestone ${milestoneId ?? ""} ${MESSAGES[reason]}`.replace("  ", " "));
    this.name = "MilestoneStateError";
  }
}

/** Names compare without regard to letter case or surrounding spaces. */
export function normalizeMilestoneName(name: string): string {
  return name.trim().toLowerCase();
}

export function isMilestoneOpen(milestone: Milestone): boolean {
  return milestone.closedAt === null;
}

/** Open, dated strictly in the past and still holding open issues. */
export function isMilestoneOverdue(
  milestone: Milestone,
  progress: MilestoneProgress,
  now: IsoTimestamp,
): boolean {
  return (
    isMilestoneOpen(milestone) &&
    milestone.targetDate !== null &&
    Date.parse(milestone.targetDate) < Date.parse(now) &&
    progress.open > 0
  );
}

/**
 * Open first, then closed; within each by target date (undated last), ties by
 * creation, oldest first.
 */
export function compareMilestones(a: Milestone, b: Milestone): number {
  const openA = isMilestoneOpen(a) ? 0 : 1;
  const openB = isMilestoneOpen(b) ? 0 : 1;
  if (openA !== openB) return openA - openB;

  if (a.targetDate !== b.targetDate) {
    if (a.targetDate === null) return 1;
    if (b.targetDate === null) return -1;
    const diff = Date.parse(a.targetDate) - Date.parse(b.targetDate);
    if (diff !== 0) return diff;
  }

  const created = Date.parse(a.createdAt) - Date.parse(b.createdAt);
  if (created !== 0) return created;
  return a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
}

export function sortMilestones(
  items: readonly MilestoneWithProgress[],
): readonly MilestoneWithProgress[] {
  return [...items].sort((a, b) => compareMilestones(a.milestone, b.milestone));
}
EOF
