function assertNameFree(
  siblings: readonly Milestone[],
  name: string,
  except: MilestoneId | null,
): void {
  const wanted = normalizeMilestoneName(name);
  const clash = siblings.find(
    (m) => m.id !== except && normalizeMilestoneName(m.name) === wanted,
  );
  if (clash) throw new MilestoneStateError("name_taken", clash.id);
}

function assertRoomForOpen(
  siblings: readonly Milestone[],
  milestoneId: MilestoneId | null,
): void {
  const open = siblings.filter(isMilestoneOpen).length;
  if (open >= MAX_OPEN_MILESTONES_PER_PROJECT) {
    throw new MilestoneStateError("too_many_open", milestoneId);
  }
}

async function withProgress(
  orgId: OrgId,
  items: readonly Milestone[],
  now: IsoTimestamp,
): Promise<readonly MilestoneWithProgress[]> {
  const counts = await issueRepo.countIssuesByMilestone(
    orgId,
    items.map((m) => m.id),
  );
  return items.map((milestone) => {
    const c = counts.get(milestone.id) ?? { total: 0, closed: 0 };
    const progress = { total: c.total, open: c.total - c.closed, closed: c.closed };
    return {
