import { afterAll, beforeAll, expect, it, vi } from "vitest";
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
import { registerEventHandlers } from "@/server/services/event-registry";
import * as ms from "@/server/services/milestone-service";
import * as issueService from "@/server/services/issue-service";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import { MilestoneStateError } from "@/lib/milestones";
import { NotFoundError } from "@/server/services/_support";
import { toAppError } from "@/lib/errors";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); registerEventHandlers(); });
afterAll(() => cleanup());

it("works", async () => {
  const t = await createTenant("ms");
  const owner = t.actors.owner;
  const a = await ms.createMilestone(owner, { orgId: t.org.id, projectId: t.project.id, name: "Alpha", targetDate: "2020-01-01T00:00:00.000Z" as never });
  const b = await ms.createMilestone(owner, { orgId: t.org.id, projectId: t.project.id, name: "Beta", targetDate: null });
  await expect(ms.createMilestone(owner, { orgId: t.org.id, projectId: t.project.id, name: " alpha ", targetDate: null })).rejects.toBeInstanceOf(MilestoneStateError);
  const i1 = await issueService.createIssue(t.actors.member, { ...issueInput(t.org.id, t.project.id, { assigneeId: t.userIds.member }), milestoneId: a.id });
  const i2 = await issueService.createIssue(owner, { ...issueInput(t.org.id, t.project.id, { assigneeId: t.userIds.admin }), milestoneId: a.id });
  const i3 = await issueService.createIssue(owner, issueInput(t.org.id, t.project.id));
  await issueService.setIssueMilestone(owner, { orgId: t.org.id, issueId: i3.id, milestoneId: a.id });
  await issueService.changeIssueStatus(owner, { orgId: t.org.id, issueId: i3.id, status: "done" });
  const list = await ms.listMilestones(t.actors.viewer, t.org.id, t.project.id);
  console.log(JSON.stringify(list.map((x) => [x.milestone.name, x.progress, x.overdue])));
